def bloco_ficha(nome):
    d = FICHAS[nome]
    termos = [t.strip() for t in re.split(r"(?=\*\*[^*]+:\*\*)", d["termos"]) if t.strip()]
    return "\n".join([
        "<!-- didatico:inicio -->", "## 🧠 Comece pelo problema", "",
        f"**Qual é a dificuldade?** {d['problema']}", "",
        f"**Como este serviço ajuda?** {d['explicacao']}", "",
        f"**Exemplo do dia a dia:** {d['exemplo']}", "",
        f"**O que ele não resolve sozinho?** {d['limite']}", "",
        "**Primeiras palavras para entender:**", "",
        *[f"- {termo}" for termo in termos], "",
        "*O exemplo é ilustrativo. Para estudar para a prova, confira o escopo indicado abaixo; "
        "para usar o serviço, confira também as condições e a documentação oficial desta ficha.*",
        "<!-- didatico:fim -->",
    ])
